import sys
from datetime import date


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def main():
    lines = [line.strip().split() for line in sys.stdin]
    ref_date = parse(lines[0][0])
    counts = {}
    for i in range(1, len(lines)):
        name, born_str = lines[i]
        born_date = parse(born_str)
        age = ref_date.year - born_date.year
        if born_date.month > ref_date.month:
            age -= 1
        elif born_date.month == ref_date.month and born_date.day > ref_date.day:
            age -= 1
        if age < 13:
            group = "child"
        elif age < 18:
            group = "teen"
        elif age < 65:
            group = "adult"
        else:
            group = "senior"
        counts[group] = counts.get(group, 0) + 1
        print(f"{name} {age} {group}")
    for group in ["child", "teen", "adult", "senior"]:
        print(f"{group} {counts.get(group, 0)}")


if __name__ == "__main__":
    main()
